'use strict';

/**
* Convert a semantic document to a Jupyter notebook.
*
* @module @stdlib/_tools/semantic-document/to-ipynb
*
* @example
* var md2doc = require( '@stdlib/_tools/semantic-document/from-markdown' );
* var doc2ipynb = require( '@stdlib/_tools/semantic-document/to-ipynb' );
*
* var doc = md2doc( '# Beep\n\n> Boop!' );
* // returns {...}
*
* var nb = doc2ipynb( doc );
* // returns {...}
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var stringify = require( './stringify.js' );
var main = require( './main.js' );


// MAIN //

setReadOnly( main, 'stringify', stringify ); // FIXME: consider moving to a separate package


// EXPORTS //

module.exports = main;
